import{_ as e,o as a,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Carpentry","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/professions/carpentry.md","filePath":"en/game-design/professions/carpentry.md"}'),s={name:"en/game-design/professions/carpentry.md"};function o(r,i,l,c,d,p){return a(),n("div",null,[...i[0]||(i[0]=[t('<h1 id="carpentry" tabindex="-1">Carpentry <a class="header-anchor" href="#carpentry" aria-label="Permalink to &quot;Carpentry&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; all mechanics, examples and technique paths below remain candidates. <strong>Implementation:</strong> no implementation of this redesign is established by this documentation batch. <strong>Availability:</strong> not established. <strong>Verification:</strong> documentation review only; no gameplay test. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/en/guide/professions/carpentry.html">Player-facing overview</a> · <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Purpose and profession loop <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Permalink to &quot;Purpose and profession loop&quot;">​</a></h2><p>Carpentry should be wood transformation and construction.</p><h3 id="core-chain" tabindex="-1">Core chain <a class="header-anchor" href="#core-chain" aria-label="Permalink to &quot;Core chain&quot;">​</a></h3><p>Season -&gt; Select -&gt; Cut -&gt; Shape -&gt; Join -&gt; Assemble -&gt; Finish</p><h3 id="possible-concepts" tabindex="-1">Possible concepts <a class="header-anchor" href="#possible-concepts" aria-label="Permalink to &quot;Possible concepts&quot;">​</a></h3><ul><li>green/damp/seasoned/dry wood;</li><li>milling into beams/planks/boards/dowels/shafts;</li><li>grain orientation;</li><li>joinery;</li><li>treatments;</li><li>finishing.</li></ul><h3 id="joinery-examples" tabindex="-1">Joinery examples <a class="header-anchor" href="#joinery-examples" aria-label="Permalink to &quot;Joinery examples&quot;">​</a></h3><ul><li>pegs;</li><li>dowels;</li><li>mortise and tenon;</li><li>dovetail;</li><li>lashing;</li><li>nails;</li><li>glue.</li></ul><p>Do not simulate woodworking at excessive granularity.</p><h3 id="products-and-construction" tabindex="-1">Products and construction <a class="header-anchor" href="#products-and-construction" aria-label="Permalink to &quot;Products and construction&quot;">​</a></h3><ul><li>furniture;</li><li>doors;</li><li>chests;</li><li>carts;</li><li>crates;</li><li>weapon handles;</li><li>shields;</li><li>structural supports;</li><li>bridges/scaffolding;</li><li>camp structures;</li><li>fortifications;</li><li>ship components in future scope;</li><li>bow components.</li></ul><h3 id="cross-skill" tabindex="-1">Cross-skill <a class="header-anchor" href="#cross-skill" aria-label="Permalink to &quot;Cross-skill&quot;">​</a></h3><ul><li>Carpentry + Camping -&gt; improved field camp structures.</li><li>Carpentry + Mining -&gt; mine supports.</li><li>Carpentry + Tinkering -&gt; mechanisms/structures.</li><li>Carpentry + Blacksmithing -&gt; composite items.</li><li>Carpentry + Archery -&gt; Bowmaking specialization.</li></ul><h2 id="bowmaking-and-fletching" tabindex="-1">Bowmaking and Fletching <a class="header-anchor" href="#bowmaking-and-fletching" aria-label="Permalink to &quot;Bowmaking and Fletching&quot;">​</a></h2><p>Bowmaking / Fletching is a technique path, not an independent skill in this proposal. The existing skill roster still requires explicit reconciliation.</p><p>Bowmaking is a specialization / technique path emerging primarily from:</p><ul><li>Carpentry;</li><li>Archery;</li></ul><p>with optional support from Tailoring and Blacksmithing.</p><p>A carpenter does not automatically know how to make bows. They must learn Bowmaking from:</p><ul><li>a teacher;</li><li>academy;</li><li>guild;</li><li>manuscript;</li><li>challenge/competition;</li><li>exploration;</li><li>another player where allowed.</li></ul><p>Likewise Luthiery may later be another Carpentry technique path.</p><p>Bowmaking chain: Select wood -&gt; Season -&gt; choose stave -&gt; shape -&gt; tiller -&gt; string -&gt; tune -&gt; test</p><p>Important concepts:</p><ul><li>wood species;</li><li>grain;</li><li>seasoning;</li><li>tillering;</li><li>draw weight;</li><li>bow form;</li><li>strings;</li><li>tuning;</li><li>test firing.</li></ul><p>Possible bow families:</p><ul><li>short bow;</li><li>longbow;</li><li>recurve/composite if setting/materials support them.</li></ul><p>Arrows:</p><ul><li>shaft;</li><li>head;</li><li>fletching;</li><li>assembly.</li></ul><p>Possible arrow identities:</p><ul><li>light;</li><li>heavy;</li><li>broadhead;</li><li>bodkin;</li><li>blunt;</li><li>later specialized/alchemical variants.</li></ul><p>A Master Bowyer should be a valuable profession identity that takes substantial time and knowledge to achieve.</p><h2 id="knowledge-and-specialization" tabindex="-1">Knowledge and specialization <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Permalink to &quot;Knowledge and specialization&quot;">​</a></h2><p><strong>Woodworker&#39;s Journal.</strong> Materials, joinery, construction and learned Bowmaking support different profession paths. Advanced Tillering and future Luthiery are techniques, not automatic abilities or new skills.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Shared progression, production and economy <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Permalink to &quot;Shared progression, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">character skill framework</a> owns teaching and cap/gain direction. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a> owns craft discovery, knowledge sharing, manual mastery, batch production, commissions and multidimensional reputation. Those rules are not independently redefined here. The <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">quality specification</a> owns the shared result envelope and rare item properties.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Related skills and field interactions <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Permalink to &quot;Related skills and field interactions&quot;">​</a></h2><p>Camping, Mining, Tinkering and Blacksmithing connect construction to camps, supports, mechanisms and composite items. Archery contributes to Bowmaking, with optional Tailoring and Blacksmithing support.</p><p><a href="/Syrolands-Public/en/game-design/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/en/game-design/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/en/game-design/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/en/game-design/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/en/game-design/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">Skill roster reconciliation</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstraction and technical boundary <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Permalink to &quot;Abstraction and technical boundary&quot;">​</a></h2><p>Keep only state and feedback that support meaningful decisions. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#performance-abstraction-and-authority">shared abstraction/authority constraints</a> and living-world architecture apply; persistence requires a separate technical design. Nothing here selects packet IDs, schemas, timers, UI assets or runtime algorithms.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Seasoning and storage; joinery granularity; structural placement/protection; bow knowledge versus skill prerequisites; Archery contribution; bow families/material eligibility; arrow roles and ammunition balance. Bowcraft skill-list/ID/character migration is unresolved and not authorized; Fletching is part of the technique path. Ship components and Luthiery remain future scope.</p><p>The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">shared reconciliation register</a> owns cross-system conflicts. Existing combat experiments and evidence do not validate this profession redesign.</p><h2 id="proposed-training-facilities-—-batch-05" tabindex="-1">Proposed training facilities — Batch 05 <a class="header-anchor" href="#proposed-training-facilities-—-batch-05" aria-label="Permalink to &quot;Proposed training facilities — Batch 05&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/characters/familiarity.html#training-facilities-and-crafts">Shared Familiarity and facilities</a> considers crafted dummies, articulated/moving targets, range mechanisms and magical practice foci, with Carpentry, Tinkering and Inscription as possible contributors. Roles/recipes are not allocated here. Facilities should efficiently maintain fluency, not become optimal core-skill grinding or bypass discovery.</p>',48)])])}const m=e(s,[["render",o]]);export{u as __pageData,m as default};
